#[derive(Clone, PartialEq)]
pub enum Value {
    Int(i64),
    Float(f64),
    Big(Decimal),
    Str(String),
    Char(char),
    Bool(bool),
    Pct(f64),
    DateTime(GoblinDateTime),
    Formatted(Box<Value>, FormatSpec),
    Array(Vec<Value>),
    Map(BTreeMap<String, Value>),
    MapOrd(IndexMap<String, Value>),
    Pair(Box<Value>, Box<Value>), // for >< (divmod)
    Seq(Seq),
    Nil,
    Unit,
    CtrlSkip,  
    CtrlStop,
    CtrlReturn(Box<Value>),
    Object {
        class_name: String,
        fields: IndexMap<String, Value>,
        readonly_fields: BTreeSet<String>,
        /// Fields inferred as traits: numeric, 0..1, not prefixed with ~ (raw).
        /// Populated at instantiation time. Used by overlays and links.
        trait_fields: BTreeSet<String>,
        /// Stable identity used to locate this object in Session::object_store.
        uuid: String,
    },
    /// Handle into Session::object_store. Stored in env frames in place of the
    /// object itself so that mutations are always applied to the single
    /// canonical copy.
    Ref(String),
    /// A spatial coordinate reference into a named GridWorld.
    /// Produced by :grid_ref(world, x, y) and returned by
    /// :grid_neighbors, :grid_occupied, :grid_cells_with.
    ///
    /// This is a pure coordinate — it carries no value itself.
    /// Use :grid_get / :grid_set to read or write the cell it names.
    GridRef {
        grid_id: String,
        x: i32,
        y: i32,
    },
    Enum {
        enum_name: String,
        variant_name: String,
        fields: Option<IndexMap<String, Value>>,
    },
    Class {
        name: String,
    },
}

#[derive(Clone, Debug, PartialEq)]
pub struct FormatSpec {
    pub decimals: u32,                  // how many decimals to display
    pub sep_thousands: Option<char>,    // ',', '.', '_', '\'' or None
    pub sep_decimal: char,              // '.' or ','
}

fn fmt_string_visible(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for ch in s.chars() {
        match ch {
            '\\' => out.push_str("\\\\"),
            '"'  => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => out.push_str(&format!("\\u{{{:x}}}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn fmt_char_visible(c: char) -> String {
    match c {
        '\\' => "'\\\\'".into(),
        '\'' => "'\\''".into(),
        '\n' => "'\\n'".into(),
        '\r' => "'\\r'".into(),
        '\t' => "'\\t'".into(),
        c if c.is_control() => format!("'\\u{{{:x}}}'", c as u32),
        c => {
            let mut s = String::with_capacity(3);
            s.push('\''); s.push(c); s.push('\''); s
        }
    }
}

#[inline]
fn escape_braces_for_raw(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for ch in s.chars() {
        match ch {
            '{' => { out.push('{'); out.push('{'); }
            '}' => { out.push('}'); out.push('}'); }
            _   => out.push(ch),
        }
    }
    out
}

#[inline]
fn synth_span() -> Span {
    // file, start, end, line_start, line_end, col_start, col_end
    Span::new("<internal>", 0, 0, 0, 0, 0, 0)
}

impl fmt::Display for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // Use depth-aware formatting to prevent stack overflow
        write!(f, "{}", fmt_value_with_depth(self, 0))
    }
}

impl fmt::Debug for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // Use depth-aware formatting to prevent stack overflow in debug output
        write!(f, "{}", fmt_value_with_depth(self, 0))
    }
}

