fn resolve_box_template(s: &str, box_store: &HashMap<String, Value>) -> String {
    let mut out = String::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '{' && i + 1 < chars.len() && chars[i + 1] == '#' {
            let start = i + 1;
            let mut j = start;
            while j < chars.len() && chars[j] != '}' { j += 1; }
            if j < chars.len() {
                let inner: String = chars[start..j].iter().collect();
                let inner = inner.trim().trim_start_matches('#');
                let key = if let Some(at) = inner.find('@') { &inner[..at] } else { inner };
                if key.contains("::") {
                    if let Some(Value::Str(v)) = box_store.get(key) {
                        out.push_str(v);
                        i = j + 1;
                        continue;
                    }
                }
            }
            // not resolved — keep literal
            out.push(chars[i]);
            i += 1;
        } else {
            out.push(chars[i]);
            i += 1;
        }
    }
    out
}

pub fn load_box_toml(sess: &mut Session, path: &std::path::Path) -> Result<(), String> {
    let content = std::fs::read_to_string(path)
        .map_err(|e| format!("Cannot read {}: {}", path.display(), e))?;

    let table: toml::Table = content.parse()
        .map_err(|e| format!("Invalid TOML in {}: {}", path.display(), e))?;

    for (namespace, section) in &table {
        if let toml::Value::Table(fields) = section {
            for (key, val) in fields {
                let v = match val {
                    toml::Value::String(s)  => Value::Str(s.clone()),
                    toml::Value::Integer(i) => Value::Int(*i),
                    toml::Value::Float(f)   => Value::Float(*f),
                    toml::Value::Boolean(b) => Value::Bool(*b),
                    other                   => Value::Str(other.to_string()),
                };
                sess.box_store.insert(format!("{}::{}", namespace, key), v);
            }
        }
    }

    // Second pass: resolve {#ns::key} and {#ns::key@source} templates
    // Iterate to a fixed point so chained dependencies resolve in order
    for _ in 0..10 {
        let mut changed = false;
        let keys: Vec<String> = sess.box_store.keys().cloned().collect();
        for k in keys {
            if let Some(Value::Str(s)) = sess.box_store.get(&k).cloned() {
                if s.contains("{#") {
                    let resolved = resolve_box_template(&s, &sess.box_store);
                    if resolved != s {
                        sess.box_store.insert(k, Value::Str(resolved));
                        changed = true;
                    }
                }
            }
        }
        if !changed { break; }
    }

    // Drop self-referential entries (e.g. portal = "{#local::portal}") — a key that
    // references itself can never resolve and must not pre-populate the box.
    sess.box_store.retain(|k, v| {
        if let Value::Str(s) = v {
            let self_ref = format!("{{#{}}}", k);
            let self_ref_ann = format!("{{#{}@", k);
            !(s.contains(&self_ref) || s.contains(&self_ref_ann))
        } else {
            true
        }
    });

    Ok(())
}

